/* Candy set additions — cards appended after candy.js.
   (candy.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'candy.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('candy');
  if (!S) return;
  var extra = [{"name":"Jolly Rancher Hard Candy Original","rarity":"legendary","id":"jolly-rancher-hard-candy-original","subtitle":"Hard Candy & Lollipops","details":"Founded in Colorado in 1949, Jolly Rancher named itself for friendly western hospitality; the hard candies dissolve slowly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jolly_Ranchers.jpg?width=1024"},{"name":"Life Savers Five Flavors Hard Candy","rarity":"legendary","id":"life-savers-five-flavors-hard-candy","subtitle":"Hard Candy & Lollipops","details":"Life Savers began in 1912 when Clarence Crane punched a hole in a mint; the Five Flavors roll made the ring candy famous.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lifesaves_fruit-candies.JPG?width=1024"},{"name":"Dum Dums Original Pops","rarity":"legendary","id":"dum-dums-original-pops","subtitle":"Hard Candy & Lollipops","details":"Spangler's pops date to 1924; the Mystery Flavor is made when one flavor's syrup runs into the next on the line.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dum_Dums_Lollipops.jpg?width=1024"},{"name":"Blow Pop Cherry","rarity":"legendary","id":"blow-pop-cherry","subtitle":"Hard Candy & Lollipops","details":"Charms' Blow Pop hides a bubble gum center inside a cherry hard candy shell, the original two-in-one lollipop.","image":"https://images.openfoodfacts.org/images/products/001/420/033/8610/front_en.5.400.jpg"},{"name":"Tootsie Pop Chocolate","rarity":"legendary","id":"tootsie-pop-chocolate","subtitle":"Hard Candy & Lollipops","details":"Tootsie Pops arrived in 1931 with candy shell over a chewy Tootsie Roll center; Mr. Owl later asked how many licks it takes.","image":"https://images.openfoodfacts.org/images/products/007/172/077/5059/front_en.3.400.jpg"},{"name":"Ring Pop Strawberry","rarity":"epic","id":"ring-pop-strawberry","subtitle":"Hard Candy & Lollipops","details":"Topps' wearable lollipop: a strawberry jewel of hard candy set in a plastic ring, licked straight off your finger.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9a/Ring_pop_on_hand.jpg"},{"name":"Werther's Original Hard Caramels","rarity":"epic","id":"werthers-original-hard-caramels","subtitle":"Hard Candy & Lollipops","details":"Storck's hard caramels carry the butter-and-cream recipe named for Werther, the German town where the candy was created.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/An_Open_Bag_of_Werther%27s_Original.jpg?width=1024"},{"name":"Wonka Nerds Grape & Strawberry","rarity":"epic","id":"wonka-nerds-grape-strawberry","subtitle":"Hard Candy & Lollipops","details":"Launched in 1983 under the Wonka name, Nerds split grape and strawberry into two chambers of one tilted box.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nerds-Candies.jpg?width=1024"},{"name":"Smarties Original Candy Rolls","rarity":"epic","id":"smarties-original-candy-rolls","subtitle":"Hard Candy & Lollipops","details":"Pressed candy tablets rolled in paper, made by the Smarties Candy Company in New Jersey since 1949.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Giant-Smarties-US.jpg?width=1024"},{"name":"Spree Original","rarity":"rare","id":"spree-original","subtitle":"Hard Candy & Lollipops","details":"Wonka's pressed fruit discs from the Spree line: sweet, chalky tablets in cherry, orange, lemon, grape and sour apple style flavors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spree-Candies.jpg?width=1024"},{"name":"Bottle Caps","rarity":"rare","id":"bottle-caps","subtitle":"Hard Candy & Lollipops","details":"Wonka's soda-shop tablets shaped like bottle caps, fizzing with root beer, cola, cherry, grape and orange soda flavors.","image":"https://upload.wikimedia.org/wikipedia/commons/2/26/Bottle_Caps_roll.jpg"},{"name":"Necco Wafers Original","rarity":"rare","id":"necco-wafers-original","subtitle":"Hard Candy & Lollipops","details":"Oliver Chase's 1847 lozenge machine made these the first commercial US candy; eight flavors share one pastel roll.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Necco-Wafers-Regular.jpg?width=1024"},{"name":"Lemonhead Original","rarity":"rare","id":"lemonhead-original","subtitle":"Hard Candy & Lollipops","details":"Ferrara's Lemonhead, from 1962, layers a sweet shell over a sour lemon core, so the bite starts soft and ends tart.","image":"https://upload.wikimedia.org/wikipedia/en/4/4e/Lemonhead_candy.jpg"},{"name":"Atomic FireBall","rarity":"rare","id":"atomic-fireball","subtitle":"Hard Candy & Lollipops","details":"Ferrara's Atomic FireBall, launched in 1954, is a cinnamon jawbreaker so hot it is eaten in stages, layer by layer.","image":"https://images.openfoodfacts.org/images/products/004/142/005/2057/front_fr.4.400.jpg"},{"name":"Everlasting Gobstopper","rarity":"rare","id":"everlasting-gobstopper","subtitle":"Hard Candy & Lollipops","details":"Wonka's Gobstopper, sold since 1976 and inspired by Roald Dahl's book, changes color and flavor as each layer dissolves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Everlasting-Gobstoppers.jpg?width=1024"},{"name":"Jawbreakers","rarity":"rare","id":"jawbreakers","subtitle":"Hard Candy & Lollipops","details":"Layered hard candy built to last for hours: compressed sugar spheres so hard that biting one is a rookie mistake.","image":"https://upload.wikimedia.org/wikipedia/commons/0/04/Jawbreaker_plate.jpg"},{"name":"Brach's Star Brites Peppermint Starlight Mints","rarity":"rare","id":"brachs-star-brites-peppermint-starlight-mints","subtitle":"Hard Candy & Lollipops","details":"Brach's pinwheel-striped peppermint discs, individually wrapped in crinkly cellophane and standard issue at restaurant tills.","image":"assets/sets/candy/images/brachs-star-brites-peppermint-starlight-mints.webp"},{"name":"Brach's Butterscotch Discs","rarity":"rare","id":"brachs-butterscotch-discs","subtitle":"Hard Candy & Lollipops","details":"Brach's golden butterscotch discs, buttery and smooth-melting, a staple of grandparents' candy dishes for generations.","image":"assets/sets/candy/images/brachs-butterscotch-discs.webp"},{"name":"Brach's Cinnamon Discs","rarity":"rare","id":"brachs-cinnamon-discs","subtitle":"Hard Candy & Lollipops","details":"Brach's cinnamon discs wrap a slow-building sweet heat in red-striped hard candy, milder than a FireBall but just as red.","image":"assets/sets/candy/images/brachs-cinnamon-discs.webp"},{"name":"Root Beer Barrels","rarity":"rare","id":"root-beer-barrels","subtitle":"Hard Candy & Lollipops","details":"Barrel-shaped hard candies with old-fashioned root beer flavor, a penny-candy counter classic sold by the scoop.","image":"assets/sets/candy/images/root-beer-barrels.webp"},{"name":"Claeys Lemon Drops","rarity":"rare","id":"claeys-lemon-drops","subtitle":"Hard Candy & Lollipops","details":"Claeys of Indiana, candy-making since 1919, makes these old-fashioned lemon drops with a sugar-dusted, kettle-cooked style.","image":"assets/sets/candy/images/claeys-lemon-drops.webp"},{"name":"Rock Candy","rarity":"uncommon","id":"rock-candy","subtitle":"Hard Candy & Lollipops","details":"Pure crystallized sugar grown on a string or stick, among the oldest candies in the world and once used as medicine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rock-Candy-Sticks.jpg?width=1024"},{"name":"Candy Buttons","rarity":"uncommon","id":"candy-buttons","subtitle":"Hard Candy & Lollipops","details":"Tiny pastel candy dots piped onto long paper strips; eating them cleanly, without a fleck of paper, is the real challenge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Candy_Buttons.jpg?width=1024"},{"name":"Push Pop Strawberry","rarity":"uncommon","id":"push-pop-strawberry","subtitle":"Hard Candy & Lollipops","details":"Topps' Push Pop saves half for later: the strawberry lollipop pushes up from its tube and caps shut between licks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Push_pops_%28candy%29.jpg?width=1024"},{"name":"Charms Mini Pops","rarity":"uncommon","id":"charms-mini-pops","subtitle":"Hard Candy & Lollipops","details":"Charms shrinks its lollipops to mini size, assorted fruit pops small enough to hand out by the fistful.","image":"https://images.openfoodfacts.org/images/products/001/420/034/0064/front_en.4.400.jpg"},{"name":"Chupa Chups Strawberry","rarity":"uncommon","id":"chupa-chups-strawberry","subtitle":"Hard Candy & Lollipops","details":"Spain's Chupa Chups began in 1958; Salvador Dali drew its daisy logo, and strawberry is its best-selling flavor worldwide.","image":"https://images.openfoodfacts.org/images/products/000/004/981/4521/front_en.29.400.jpg"},{"name":"Jolly Rancher Green Apple Hard Candy","rarity":"uncommon","id":"jolly-rancher-green-apple-hard-candy","subtitle":"Hard Candy & Lollipops","details":"Jolly Rancher's green apple hard candy, tart and orchard-sharp, one of the Colorado brand's defining original flavors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2019-11-09_17_56_34_An_apple-flavored_Jolly_Rancher_Hard_Candy_Stix_after_being_unwrapped_in_the_Dulles_section_of_Sterling%2C_Loudoun_County%2C_Virginia.jpg?width=1024"},{"name":"Jolly Rancher Watermelon Hard Candy","rarity":"uncommon","id":"jolly-rancher-watermelon-hard-candy","subtitle":"Hard Candy & Lollipops","details":"Watermelon is Jolly Rancher's fan-voted favorite flavor, a sweet summer melon taste in a slow-dissolving rectangle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2019-11-08_14_19_58_A_watermelon-flavored_Jolly_Rancher_Hard_Candy_Stix_after_being_unwrapped_in_the_Dulles_section_of_Sterling%2C_Loudoun_County%2C_Virginia.jpg?width=1024"},{"name":"Jolly Rancher Cherry Lollipops","rarity":"uncommon","id":"jolly-rancher-cherry-lollipops","subtitle":"Hard Candy & Lollipops","details":"Jolly Rancher's cherry on a stick: the brand's hard candy formula poured as a flat, long-lasting lollipop.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2019-11-11_20_36_15_An_unwrapped_Jolly_Rancher_Cherry_Lollipop_in_the_Dulles_section_of_Sterling%2C_Loudoun_County%2C_Virginia.jpg?width=1024"},{"name":"Claeys Watermelon Hard Candies","rarity":"uncommon","id":"claeys-watermelon-hard-candies","subtitle":"Hard Candy & Lollipops","details":"Claeys' watermelon hard candies bring summer melon flavor to the Indiana maker's old-fashioned, sugar-dusted drop line.","image":"assets/sets/candy/images/claeys-watermelon-hard-candies.webp"},{"name":"Claeys Cherry Hard Candies","rarity":"uncommon","id":"claeys-cherry-hard-candies","subtitle":"Hard Candy & Lollipops","details":"Claeys' cherry drops follow the maker's 1919 kettle tradition, tart-sweet hard candy with a light sugar dusting.","image":"assets/sets/candy/images/claeys-cherry-hard-candies.webp"},{"name":"Reed's Butterscotch Rolls","rarity":"uncommon","id":"reeds-butterscotch-rolls","subtitle":"Hard Candy & Lollipops","details":"Reed's butterscotch comes in rolls of individually wrapped discs, a smooth, slow-melt candy dating to Chicago's Reed's Candy.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1d/1968_Ad_better_quality_all_rolls_reeds.jpg"},{"name":"Reed's Root Beer Rolls","rarity":"uncommon","id":"reeds-root-beer-rolls","subtitle":"Hard Candy & Lollipops","details":"Reed's root beer discs capture sassafras soda flavor in roll form, from the Chicago candy house founded in 1893.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1d/1968_Ad_better_quality_all_rolls_reeds.jpg"},{"name":"Regal Crown Sour Cherry","rarity":"uncommon","id":"regal-crown-sour-cherry","subtitle":"Hard Candy & Lollipops","details":"A revived retro roll: sour cherry hard candies once imported from Britain, brought back by popular demand after vanishing.","image":"assets/sets/candy/images/regal-crown-sour-cherry.webp"},{"name":"Boston Baked Beans","rarity":"uncommon","id":"boston-baked-beans","subtitle":"Hard Candy & Lollipops","details":"Ferrara's candy-coated peanuts wear a shiny brown shell and no beans at all; the name nods to Boston's baked bean pots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ferrara-Pan-Boston-Baked-Beans.jpg?width=1024"},{"name":"French Burnt Peanuts","rarity":"uncommon","id":"french-burnt-peanuts","subtitle":"Hard Candy & Lollipops","details":"Peanuts in a crunchy, bright red candy shell with a faint French-roast bitterness, a diner-counter and ballpark classic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/French_Burnt_Peanuts_%28bag_interior%29.jpg?width=1024"},{"name":"Jordan Almonds","rarity":"uncommon","id":"jordan-almonds","subtitle":"Hard Candy & Lollipops","details":"Sugar-panned almonds in pastel shells, served at weddings for centuries; tradition gives guests five, for five wishes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/La-Pone-Jordan-Almonds.jpg?width=1024"},{"name":"Runts","rarity":"uncommon","id":"runts","subtitle":"Hard Candy & Lollipops","details":"Wonka's Runts, from 1982, are crunchy candies molded as tiny bananas, oranges, grapes and strawberries, shell and all.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7d/Runts-2013.jpg"},{"name":"Red Hots","rarity":"common","id":"red-hots","subtitle":"Hard Candy & Lollipops","details":"Ferrara's tiny cinnamon Imperials, nicknamed Red Hots, deliver concentrated cinnamon heat a pinch at a time.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ferrara-Pan-Red-Hots-Candy.jpg?width=1024"},{"name":"Astro Pop Original","rarity":"common","id":"astro-pop-original","subtitle":"Hard Candy & Lollipops","details":"The rocket-shaped Astro Pop, created in 1963 by two rocket scientists, stacks cherry, passion fruit and pineapple layers.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0f/Astro_Pops_Candy.JPG"},{"name":"Giant Smarties","rarity":"common","id":"giant-smarties","subtitle":"Hard Candy & Lollipops","details":"Giant Smarties scale the pressed tablet up: the same tart-sweet Smarties flavor in oversized, shareable discs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US-Smarties-Candy-wWrapper.jpg?width=1024"},{"name":"Candy Necklace","rarity":"common","id":"candy-necklace","subtitle":"Hard Candy & Lollipops","details":"A wearable string of pastel candy beads on elastic cord, eaten one chalky, fruit-flavored bead at a time off your neck.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Candy-Bead-Necklace.jpg?width=1024"},{"name":"Gilliam Old Fashioned Peppermint Stick Candy","rarity":"common","id":"gilliam-old-fashioned-peppermint-stick-candy","subtitle":"Hard Candy & Lollipops","details":"Gilliam's old-fashioned peppermint sticks are soft-bite striped candy, made for stirring into cocoa or eating straight.","image":"assets/sets/candy/images/gilliam-old-fashioned-peppermint-stick-candy.webp"},{"name":"Life Savers Pep O Mint","rarity":"common","id":"life-savers-pep-o-mint","subtitle":"Hard Candy & Lollipops","details":"Pep O Mint is Life Savers' cool white mint roll, a pocket staple from the ring candy line that began in 1912.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Life_Savers_Pep-o-mint_ad.jpg?width=1024"},{"name":"Life Savers Butter Rum","rarity":"common","id":"life-savers-butter-rum","subtitle":"Hard Candy & Lollipops","details":"Life Savers' butter rum roll tastes like the cocktail's candy cousin: warm, buttery and caramel-sweet, in ring form.","image":"https://images.openfoodfacts.org/images/products/002/200/028/0367/front_en.13.400.jpg"},{"name":"Horehound Old Fashioned Candy","rarity":"common","id":"horehound-old-fashioned-candy","subtitle":"Hard Candy & Lollipops","details":"Old-fashioned horehound drops are bittersweet herbal candies made from the horehound plant, a cough-remedy era survivor.","image":"https://images.openfoodfacts.org/images/products/005/229/530/6176/front_en.3.400.jpg"},{"name":"Sweetarts Original Rolls","rarity":"common","id":"sweetarts-original-rolls","subtitle":"Hard Candy & Lollipops","details":"SweeTarts debuted in 1963, compressing Pixy Stix powder into tart tablets rolled in paper: cherry, grape, lemon, lime and orange.","image":"assets/sets/candy/images/sweetarts-original-rolls.webp"},{"name":"Charms Blow Pop Blue Razz Berry","rarity":"common","id":"charms-blow-pop-blue-razz-berry","subtitle":"Hard Candy & Lollipops","details":"Charms wraps blue raspberry hard candy around a bubble gum core, Blow Pop's blue-raspberry take on the two-in-one pop.","image":"assets/sets/candy/images/charms-blow-pop-blue-razz-berry.webp"},{"name":"Dum Dums Cotton Candy Pop","rarity":"common","id":"dum-dums-cotton-candy-pop","subtitle":"Hard Candy & Lollipops","details":"Cotton candy is one of Dum Dums' most-loved flavors, spinning fairground taste into a small, long-lasting pop.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dum_Dums_Lollipops.jpg?width=1024"},{"name":"Tootsie Pop Raspberry","rarity":"common","id":"tootsie-pop-raspberry","subtitle":"Hard Candy & Lollipops","details":"The raspberry Tootsie Pop wears a blue wrapper and hides the same chewy chocolate center as every flavor in the line.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/State_Fair_of_Virginia_-_Tootsie_Pop.jpg?width=1024"},{"name":"Sour Patch Kids Original","rarity":"chase","id":"sour-patch-kids-original","subtitle":"Sour","details":"First sour, then sweet: the kid-shaped gummies were created in Canada in the 1970s and renamed for the 1980s doll craze.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sour-Patch-Kids.jpg?width=1024"},{"name":"Warheads Extreme Sour Hard Candy","rarity":"legendary","id":"warheads-extreme-sour-hard-candy","subtitle":"Sour","details":"Warheads' extreme sour hard candy coats a sweet core in malic acid, so the first half-minute is a genuine endurance test.","image":"https://images.openfoodfacts.org/images/products/003/213/421/5319/front_en.3.400.jpg"},{"name":"Sour Skittles","rarity":"epic","id":"sour-skittles","subtitle":"Sour","details":"Sour Skittles keep the fruity shell-and-chew formula but roll every piece in a puckering citric acid sour sanding.","image":"assets/sets/candy/images/sour-skittles.webp"},{"name":"Starburst Sour Gummies","rarity":"rare","id":"starburst-sour-gummies","subtitle":"Sour","details":"Starburst's sour gummies take the fruit chew flavors tart, in soft gummy form with a sour sugar coating.","image":"https://images.openfoodfacts.org/images/products/002/200/007/9299/front_en.4.400.jpg"},{"name":"Trolli Sour Brite Crawlers","rarity":"legendary","id":"trolli-sour-brite-crawlers","subtitle":"Sour","details":"Trolli's sour gummy worms pair two flavors per worm, like cherry-lemon and strawberry-grape, under a sour sugar crust.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trolli_Sour_Brite_Crawlers_gummi_worms_close_up.jpg?width=1024"},{"name":"Sour Punch Blue Raspberry Straws","rarity":"epic","id":"sour-punch-blue-raspberry-straws","subtitle":"Sour","details":"American Licorice's Sour Punch straws are hollow, citric-acid-coated ropes; blue raspberry is the line's electric signature.","image":"assets/sets/candy/images/sour-punch-blue-raspberry-straws.webp"},{"name":"Sour Punch Tropical Bites","rarity":"rare","id":"sour-punch-tropical-bites","subtitle":"Sour","details":"Sour Punch in bite-size form: soft tropical-flavored pieces tumbled in the brand's signature sour sugar blend.","image":"https://images.openfoodfacts.org/images/products/004/136/408/7382/front_en.10.400.jpg"},{"name":"Airheads Xtremes Rainbow Berry Sour Belts","rarity":"rare","id":"airheads-xtremes-rainbow-berry-sour-belts","subtitle":"Sour","details":"Perfetti's rainbow belts layer berry-flavored sour strips in a long, peelable ribbon with a serious citric tang.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sour_rainbow_belts.jpg?width=1024"},{"name":"Warheads Sour Jelly Beans","rarity":"rare","id":"warheads-sour-jelly-beans","subtitle":"Sour","details":"Warheads' jelly beans shrink the brand's sour shock into chewy beans in lemon, blue raspberry, cherry and watermelon flavors.","image":"https://images.openfoodfacts.org/images/products/003/213/423/5003/front_en.3.400.jpg"},{"name":"Warheads Super Sour Spray","rarity":"rare","id":"warheads-super-sour-spray","subtitle":"Sour","details":"Warheads in a spray bottle: a few pumps of super sour liquid candy deliver the brand's pucker without the hard candy wait.","image":"assets/sets/candy/images/warheads-super-sour-spray.webp"},{"name":"Warheads Sour Cubes","rarity":"rare","id":"warheads-sour-cubes","subtitle":"Sour","details":"Warheads Sour Cubes soften the formula into chewy, sugar-dusted cubes that stay sour longer than the spray or beans.","image":"assets/sets/candy/images/warheads-sour-cubes.webp"},{"name":"Toxic Waste Hazardously Sour Candy","rarity":"rare","id":"toxic-waste-hazardously-sour-candy","subtitle":"Sour","details":"Toxic Waste packs its hazardously sour hard candies in a yellow toxic-barrel drum and dares fans to time the pucker.","image":"https://upload.wikimedia.org/wikipedia/en/0/05/Toxic_Waste_candy_products.jpg"},{"name":"Sour Jacks Original","rarity":"rare","id":"sour-jacks-original","subtitle":"Sour","details":"Sour Jacks' wedge-shaped gummies bite back: a soft chew under sour sugar, in mixed fruit flavors with a puckery finish.","image":"assets/sets/candy/images/sour-jacks-original.webp"},{"name":"Sour Jacks Watermelon","rarity":"rare","id":"sour-jacks-watermelon","subtitle":"Sour","details":"Sour Jacks cuts its gummies like watermelon wedges for this flavor, green rind edge and all, under the sour coating.","image":"assets/sets/candy/images/sour-jacks-watermelon.webp"},{"name":"SweeTarts Chewy Sours","rarity":"rare","id":"sweetarts-chewy-sours","subtitle":"Sour","details":"SweeTarts Chewy Sours began life as Shock Tarts in the 1990s, tangy chewy discs later folded into the SweeTarts family.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nestle-SweeTarts-Candies.jpg?width=1024"},{"name":"SweeTarts Ropes Twisted Rainbow Punch","rarity":"rare","id":"sweetarts-ropes-twisted-rainbow-punch","subtitle":"Sour","details":"SweeTarts Ropes twist a soft rainbow punch chew around a fruity filling, a bendy candy that started out as Kazoozles.","image":"https://images.openfoodfacts.org/images/products/007/920/005/0528/front_en.3.400.jpg"},{"name":"SweeTarts Extreme Sour Chewy","rarity":"rare","id":"sweetarts-extreme-sour-chewy","subtitle":"Sour","details":"SweeTarts turned up loud: the Extreme Sour Chewy line pushes the brand's tang to its sharpest chewy setting.","image":"assets/sets/candy/images/sweetarts-extreme-sour-chewy.webp"},{"name":"Nerds Sour Big Chewy","rarity":"rare","id":"nerds-sour-big-chewy","subtitle":"Sour","details":"Nerds Sour Big Chewy supersizes the tiny candy: a crunchy Nerds shell wrapped around a soft, sour, chewy center.","image":"https://images.openfoodfacts.org/images/products/542/502/890/5284/front_fr.3.400.jpg"},{"name":"Trolli Sour Brite Crawlers Very Berry","rarity":"rare","id":"trolli-sour-brite-crawlers-very-berry","subtitle":"Sour","details":"Trolli's Very Berry crawlers swap the classic worm flavor pairs for raspberry and blueberry combinations, sour-sanded.","image":"https://images.openfoodfacts.org/images/products/004/142/011/5875/front_en.6.400.jpg"},{"name":"Trolli Sour Brite Octopus","rarity":"rare","id":"trolli-sour-brite-octopus","subtitle":"Sour","details":"Trolli stretches its sour gummy into an eight-legged octopus, each tentacle dusted in the Brite Crawlers sour sugar.","image":"https://images.openfoodfacts.org/images/products/004/142/007/0006/front_en.3.400.jpg"},{"name":"Trolli Sour Brite Eggs","rarity":"uncommon","id":"trolli-sour-brite-eggs","subtitle":"Sour","details":"Trolli's Sour Brite Eggs hide a gummy yolk-and-white design inside a sour-sanded shell, an Easter-basket regular.","image":"https://images.openfoodfacts.org/images/products/004/142/004/5080/front_en.3.400.jpg"},{"name":"Sour Patch Kids Watermelon","rarity":"uncommon","id":"sour-patch-kids-watermelon","subtitle":"Sour","details":"Sour Patch Kids gone melon: watermelon-slice-shaped gummies with the brand's trademark sour-then-sweet one-two punch.","image":"https://images.openfoodfacts.org/images/products/007/046/200/8241/front_en.19.400.jpg"},{"name":"Sour Patch Kids Extreme","rarity":"uncommon","id":"sour-patch-kids-extreme","subtitle":"Sour","details":"Sour Patch Kids Extreme cranks the sour coating past the original, aimed at fans who found the classic too gentle.","image":"assets/sets/candy/images/sour-patch-kids-extreme.webp"},{"name":"Sour Patch Kids Blue Raspberry","rarity":"uncommon","id":"sour-patch-kids-blue-raspberry","subtitle":"Sour","details":"Blue raspberry joins the Sour Patch lineup as a single-flavor bag, dyed bright blue and still sour before sweet.","image":"assets/sets/candy/images/sour-patch-kids-blue-raspberry.webp"},{"name":"Sour Patch Kids Strawberry","rarity":"uncommon","id":"sour-patch-kids-strawberry","subtitle":"Sour","details":"Strawberry Sour Patch Kids keep the kid shape and sour sanding, swapping the mixed bag for one berry flavor throughout.","image":"https://images.openfoodfacts.org/images/products/007/046/200/8227/front_en.3.400.jpg"},{"name":"Sour Patch Kids Tropical","rarity":"uncommon","id":"sour-patch-kids-tropical","subtitle":"Sour","details":"The tropical Sour Patch mix trades orchard fruits for pineapple, mango and tropical punch style flavors, still sour-first.","image":"https://images.openfoodfacts.org/images/products/007/046/200/2027/front_en.11.400.jpg"},{"name":"Haribo Sour Goldbears","rarity":"uncommon","id":"haribo-sour-goldbears","subtitle":"Sour","details":"Haribo sours its Goldbears, the gummy Hans Riegel invented in 1922, with a citric coating over the classic fruit flavors.","image":"assets/sets/candy/images/haribo-sour-goldbears.webp"},{"name":"Haribo Z!ng Sour Streamers","rarity":"uncommon","id":"haribo-z-ng-sour-streamers","subtitle":"Sour","details":"Haribo's Z!ng Streamers are wavy, flat sour strips in fruit flavors, rippled like ribbons and dusted with sour sugar.","image":"assets/sets/candy/images/haribo-z-ng-sour-streamers.webp"},{"name":"Albanese Sour 12 Flavor Gummi Bears","rarity":"uncommon","id":"albanese-sour-12-flavor-gummi-bears","subtitle":"Sour","details":"Albanese of Indiana makes its sour bears in twelve flavors, the tart counterpart to its flagship gummi bear lineup.","image":"assets/sets/candy/images/albanese-sour-12-flavor-gummi-bears.webp"},{"name":"Black Forest Sour Heads","rarity":"uncommon","id":"black-forest-sour-heads","subtitle":"Sour","details":"Black Forest's Sour Heads are fruit-flavored gummy heads with a sour bite, from Ferrara's Black Forest gummy brand.","image":"assets/sets/candy/images/black-forest-sour-heads.webp"},{"name":"Cry Baby Tears Extra Sour","rarity":"uncommon","id":"cry-baby-tears-extra-sour","subtitle":"Sour","details":"Cry Baby Tears are tear-shaped extra sour hard candies, the hard candy offshoot of the Cry Baby bubble gum line.","image":"https://images.openfoodfacts.org/images/products/005/964/200/6420/front_fr.6.400.jpg"},{"name":"Cry Baby Nitro Sours","rarity":"uncommon","id":"cry-baby-nitro-sours","subtitle":"Sour","details":"Cry Baby Nitro Sours push the Tears formula further, hard candies built for maximum pucker in a small, intense piece.","image":"https://images.openfoodfacts.org/images/products/006/285/152/6238/front_fr.3.400.jpg"},{"name":"Too Tarts Sour Spray","rarity":"uncommon","id":"too-tarts-sour-spray","subtitle":"Sour","details":"Too Tarts' sour spray candy comes in a pump bottle for tongue-painting blasts of liquid tartness, no chewing required.","image":"assets/sets/candy/images/too-tarts-sour-spray.webp"},{"name":"Airheads Xtremes Sour Bites","rarity":"uncommon","id":"airheads-xtremes-sour-bites","subtitle":"Sour","details":"Airheads Xtremes Sour Bites cut the rainbow belts into poppable pieces, each rolled in sour crystals for extra pucker.","image":"assets/sets/candy/images/airheads-xtremes-sour-bites.webp"},{"name":"Starburst Sour Jellybeans","rarity":"uncommon","id":"starburst-sour-jellybeans","subtitle":"Sour","details":"A discontinued Starburst detour: sour jellybeans in the brand's fruit flavors, gone from shelves but remembered by sour fans.","image":"assets/sets/candy/images/starburst-sour-jellybeans.webp"},{"name":"Jolly Rancher Sour Surge","rarity":"uncommon","id":"jolly-rancher-sour-surge","subtitle":"Sour","details":"This discontinued Jolly Rancher candy hid sour powder inside hard candy, so the pucker surged halfway through each piece.","image":"https://images.openfoodfacts.org/images/products/001/070/045/0296/front_en.13.400.jpg"},{"name":"Trolli Sour Brite Crawlers Minis","rarity":"uncommon","id":"trolli-sour-brite-crawlers-minis","subtitle":"Sour","details":"Trolli's crawlers in miniature: bite-size sour worms with the same two-flavor pairings, made for eating by the handful.","image":"https://images.openfoodfacts.org/images/products/004/142/007/7012/front_en.3.400.jpg"},{"name":"Sour Baby Bottle Pop Blue Raspberry","rarity":"uncommon","id":"sour-baby-bottle-pop-blue-raspberry","subtitle":"Sour","details":"The Sour Baby Bottle Pop dips a blue raspberry lollipop top into sour powder, shaking the bottle to coat every lick.","image":"https://images.openfoodfacts.org/images/products/587/426/931/0553/front_fr.3.400.jpg"},{"name":"Push Pop Gummy Roll Sour Blue Raspberry","rarity":"common","id":"push-pop-gummy-roll-sour-blue-raspberry","subtitle":"Sour","details":"Bazooka's Push Pop Gummy Roll unspools a ribbon of sour blue raspberry gummy from a wearable, click-open dispenser ring.","image":"https://images.openfoodfacts.org/images/products/004/111/625/5007/front_en.14.400.jpg"},{"name":"Toxic Waste Slime Licker Sour Rolling Candy","rarity":"common","id":"toxic-waste-slime-licker-sour-rolling-candy","subtitle":"Sour","details":"Toxic Waste's Slime Licker rolls a ball applicator across the tongue, painting on liquid sour candy straight from the bottle.","image":"https://upload.wikimedia.org/wikipedia/en/0/05/Toxic_Waste_candy_products.jpg"},{"name":"Trident Original Gum","rarity":"legendary","id":"trident-original-gum","subtitle":"Gum & Mints","details":"Trident, launched in 1964, was the first nationally marketed sugar-free gum in the US; the original is a clean peppermint.","image":"assets/sets/candy/images/trident-original-gum.webp"},{"name":"Extra Peppermint Gum","rarity":"epic","id":"extra-peppermint-gum","subtitle":"Gum & Mints","details":"Wrigley's Extra, launched in 1984 as a long-lasting sugar-free stick, made peppermint its blue-pack flagship flavor.","image":"https://images.openfoodfacts.org/images/products/000/000/228/9106/front_en.49.400.jpg"},{"name":"Orbit Peppermint Gum","rarity":"epic","id":"orbit-peppermint-gum","subtitle":"Gum & Mints","details":"Orbit's peppermint pellets come in a blister pack, sugar-free and marketed on leaving a clean, just-brushed feeling.","image":"https://images.openfoodfacts.org/images/products/000/000/224/8604/front_en.3.400.jpg"},{"name":"Juicy Fruit Original Gum","rarity":"epic","id":"juicy-fruit-original-gum","subtitle":"Gum & Mints","details":"Wrigley's Juicy Fruit has been chewed since 1893; its exact fruit flavor blend remains a closely kept company secret.","image":"https://upload.wikimedia.org/wikipedia/commons/0/09/Wrigley%27s_Juicy_Fruit.jpg"},{"name":"Altoids Peppermint Mints","rarity":"legendary","id":"altoids-peppermint-mints","subtitle":"Gum & Mints","details":"Altoids date to 1780s London, where Smith and Company made the 'curiously strong' peppermint lozenges still sold in tins.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0b/Minty_%2834757056%29.jpg"},{"name":"Tic Tac Freshmints","rarity":"epic","id":"tic-tac-freshmints","subtitle":"Gum & Mints","details":"Ferrero launched Tic Tacs in 1969; the name imitates the rattling sound the mints make shaken in their flip-top box.","image":"https://images.openfoodfacts.org/images/products/000/980/000/7615/front_en.19.400.jpg"},{"name":"Dubble Bubble Original Gum","rarity":"legendary","id":"dubble-bubble-original-gum","subtitle":"Gum & Mints","details":"Walter Diemer invented Dubble Bubble at Fleer in 1928, tinting it pink because that was the only dye he had on hand.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dubble_Bubble_Bubble_Gum.jpg?width=1024"},{"name":"Bazooka Original Bubble Gum","rarity":"epic","id":"bazooka-original-bubble-gum","subtitle":"Gum & Mints","details":"Topps launched Bazooka in 1947, naming the gum for the anti-tank weapon; Bazooka Joe comics joined the wrapper in 1953.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4f/Bazooka_gum.jpg"},{"name":"Wrigley's Spearmint Gum","rarity":"rare","id":"wrigleys-spearmint-gum","subtitle":"Gum & Mints","details":"Wrigley's Spearmint arrived in 1893, one of William Wrigley Jr.'s first two gums, in the green-arrow pack still used today.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mars_Wrigleys_deutschePackung_15Stk.jpg?width=1024"},{"name":"Doublemint Gum","rarity":"rare","id":"doublemint-gum","subtitle":"Gum & Mints","details":"Wrigley's Doublemint, from 1914, doubled down on mint and later advertising alike with its famous Doublemint Twins.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Doublemint_chewing_gum.jpg?width=1024"},{"name":"Big Red Gum","rarity":"rare","id":"big-red-gum","subtitle":"Gum & Mints","details":"Wrigley's Big Red, launched in 1975, is a cinnamon gum so tied to romance its jingle promised to 'kiss a little longer.'","image":"https://upload.wikimedia.org/wikipedia/commons/9/97/Flickr_-_cyclonebill_-_Kaneltyggegummi.jpg"},{"name":"Winterfresh Gum","rarity":"rare","id":"winterfresh-gum","subtitle":"Gum & Mints","details":"Wrigley's Winterfresh, from 1994, chills spearmint with extra cooling agents for an icy, long-lasting chew.","image":"assets/sets/candy/images/winterfresh-gum.webp"},{"name":"Hubba Bubba Max Strawberry Watermelon Gum","rarity":"rare","id":"hubba-bubba-max-strawberry-watermelon-gum","subtitle":"Gum & Mints","details":"Hubba Bubba Max layers strawberry and watermelon in one chunk, built soft so young chewers can blow oversized bubbles.","image":"https://images.openfoodfacts.org/images/products/006/490/000/0638/front_en.3.400.jpg"},{"name":"Bubble Yum Cotton Candy Gum","rarity":"rare","id":"bubble-yum-cotton-candy-gum","subtitle":"Gum & Mints","details":"Bubble Yum, the first soft bubble gum when it launched in 1975, spins its cotton candy flavor pink and fairground-sweet.","image":"https://images.openfoodfacts.org/images/products/003/400/071/1567/front_en.3.400.jpg"},{"name":"Big League Chew Original Bubble Gum","rarity":"rare","id":"big-league-chew-original-bubble-gum","subtitle":"Gum & Mints","details":"Big League Chew was dreamed up by minor league ballplayers in 1977: shredded bubble gum in a pouch, like a ballplayer's chew.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wrigley%27s_Big_League_Chew_bubble_gum.JPG?width=1024"},{"name":"Hubba Bubba Bubble Tape Original","rarity":"rare","id":"hubba-bubba-bubble-tape-original","subtitle":"Gum & Mints","details":"Hubba Bubba's Bubble Tape rolls six feet of pink bubble gum into a tape dispenser, 'for you, not them,' as ads insisted.","image":"https://images.openfoodfacts.org/images/products/002/211/007/9806/front_en.56.400.jpg"},{"name":"5 Gum Cobalt Peppermint","rarity":"rare","id":"5-gum-cobalt-peppermint","subtitle":"Gum & Mints","details":"Wrigley's 5 Gum, launched in 2007 in black foil packs, named Cobalt for its deep-cooling peppermint flavor.","image":"https://images.openfoodfacts.org/images/products/002/200/000/5120/front_en.39.400.jpg"},{"name":"Extra Spearmint Gum","rarity":"rare","id":"extra-spearmint-gum","subtitle":"Gum & Mints","details":"Extra's spearmint wears the green pack: a softer, leafier mint than the peppermint original, in the same slim sticks.","image":"https://images.openfoodfacts.org/images/products/400/990/054/7680/front_en.3.400.jpg"},{"name":"Orbit Sweet Mint Gum","rarity":"rare","id":"orbit-sweet-mint-gum","subtitle":"Gum & Mints","details":"Orbit's Sweet Mint is the line's gentle option, a sweet, mild mint pellet closer to bubblemint than to peppermint.","image":"https://images.openfoodfacts.org/images/products/400/990/054/9981/front_en.10.400.jpg"},{"name":"Trident Tropical Twist Gum","rarity":"rare","id":"trident-tropical-twist-gum","subtitle":"Gum & Mints","details":"Trident's Tropical Twist blends pineapple and mango into sugar-free sticks, a fruit detour from the brand's mint roots.","image":"https://images.openfoodfacts.org/images/products/001/254/601/4175/front_en.8.400.jpg"},{"name":"Trident Bubblegum","rarity":"uncommon","id":"trident-bubblegum","subtitle":"Gum & Mints","details":"Trident does bubblegum: pink bubblegum flavor in the brand's sugar-free stick format, bubbles without the sugar.","image":"https://images.openfoodfacts.org/images/products/001/254/601/1440/front_en.22.400.jpg"},{"name":"Mentos Pure Fresh Mint Gum","rarity":"uncommon","id":"mentos-pure-fresh-mint-gum","subtitle":"Gum & Mints","details":"Mentos Pure Fresh packs sugar-free mint gum pellets in a flip-top bottle, with green tea extract in the recipe.","image":"https://upload.wikimedia.org/wikipedia/en/3/3d/Mentossugarfree.jpg"},{"name":"Mentos Mint Chewy Mints","rarity":"uncommon","id":"mentos-mint-chewy-mints","subtitle":"Gum & Mints","details":"Mentos began in the Netherlands in 1932; the mint dragee's hard shell gives way to a chewy center in three stacked rolls.","image":"assets/sets/candy/images/mentos-mint-chewy-mints.webp"},{"name":"Mentos Fruit Chewy Mints","rarity":"uncommon","id":"mentos-fruit-chewy-mints","subtitle":"Gum & Mints","details":"Mentos Fruit mixes strawberry, orange and lemon dragees in one roll, the chewy candy shell over a fruity center.","image":"assets/sets/candy/images/mentos-fruit-chewy-mints.webp"},{"name":"Ice Breakers Wintergreen Mints","rarity":"uncommon","id":"ice-breakers-wintergreen-mints","subtitle":"Gum & Mints","details":"Ice Breakers mints hide visible flavor crystals in each disc, so wintergreen freshness arrives in little bursts.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c1/Scotch_mints.JPG"},{"name":"Ice Breakers Ice Cubes Peppermint Gum","rarity":"uncommon","id":"ice-breakers-ice-cubes-peppermint-gum","subtitle":"Gum & Mints","details":"Ice Breakers Ice Cubes are chunky peppermint gum cubes coated in cooling crystals, sold in a cup-style bottle.","image":"https://images.openfoodfacts.org/images/products/003/400/070/1742/front_fr.13.400.jpg"},{"name":"Life Savers Wint O Green Mints","rarity":"uncommon","id":"life-savers-wint-o-green-mints","subtitle":"Gum & Mints","details":"Wint O Green Life Savers famously spark in the dark when bitten, a trick of wintergreen oil called triboluminescence.","image":"assets/sets/candy/images/life-savers-wint-o-green-mints.webp"},{"name":"Breath Savers Peppermint Mints","rarity":"uncommon","id":"breath-savers-peppermint-mints","subtitle":"Gum & Mints","details":"Breath Savers' peppermint mints use an odor-neutralizing ingredient and a ring shape, sugar-free freshness since the 1970s line began.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Breathsavers-Peppermint.jpg?width=1024"},{"name":"Certs Wintergreen Breath Mints","rarity":"uncommon","id":"certs-wintergreen-breath-mints","subtitle":"Gum & Mints","details":"Certs, sold since 1956, bragged of 'two mints in one' thanks to Retsyn, its trademark blend with a drop of wintergreen oil.","image":"assets/sets/candy/images/certs-wintergreen-breath-mints.webp"},{"name":"Tic Tac Orange","rarity":"uncommon","id":"tic-tac-orange","subtitle":"Gum & Mints","details":"Tic Tac's orange mints tint both candy and box lid orange, a sweet citrus counterpoint to the original fresh mint.","image":"https://images.openfoodfacts.org/images/products/800/050/016/4976/front_de.26.400.jpg"},{"name":"Tic Tac Wintergreen","rarity":"uncommon","id":"tic-tac-wintergreen","subtitle":"Gum & Mints","details":"Tic Tac Wintergreen dyes its tiny mints pale green, trading peppermint's snap for wintergreen's smoother chill.","image":"assets/sets/candy/images/tic-tac-wintergreen.webp"},{"name":"Altoids Wintergreen Mints","rarity":"uncommon","id":"altoids-wintergreen-mints","subtitle":"Gum & Mints","details":"Altoids' wintergreen tin applies the 'curiously strong' formula to wintergreen, sharper and cooler than the peppermint.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Altoidstins1b.jpg?width=1024"},{"name":"Black Jack Gum","rarity":"uncommon","id":"black-jack-gum","subtitle":"Gum & Mints","details":"Black Jack, from 1884, was America's first flavored gum and first sold in sticks; its flavor is anise, like black licorice.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a2/Black_jacks_gum2.jpg"},{"name":"Super Bubble Original Gum","rarity":"uncommon","id":"super-bubble-original-gum","subtitle":"Gum & Mints","details":"Super Bubble's individually wrapped pink chunks were a penny-gum staple, soft enough for big bubbles at a bargain price.","image":"https://upload.wikimedia.org/wikipedia/en/5/56/Super_Bubble_Gum.jpg"},{"name":"Rain-Blo Bubble Gum Balls","rarity":"uncommon","id":"rain-blo-bubble-gum-balls","subtitle":"Gum & Mints","details":"Rain-Blo's hollow, candy-shelled gum balls brought color to the gumball machine, in fruit flavors behind the glass globe.","image":"https://upload.wikimedia.org/wikipedia/commons/0/08/Rainblo_and_Jumblo_Gum_comparison.jpg"},{"name":"Fruit Stripe Gum","rarity":"uncommon","id":"fruit-stripe-gum","subtitle":"Gum & Mints","details":"Fruit Stripe, launched in 1969 with Yipes the zebra, paired striped sticks and wrapper tattoos; it was discontinued in 2024.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fruit-Stipe-Gum-Sticks.jpg?width=1024"},{"name":"Chiclets Peppermint Gum","rarity":"uncommon","id":"chiclets-peppermint-gum","subtitle":"Gum & Mints","details":"Chiclets are tiny candy-coated gum squares named for chicle, the tree sap base; the peppermint box is now a rare US find.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Promotional_Chiclets.JPG?width=1024"},{"name":"Beemans Gum","rarity":"uncommon","id":"beemans-gum","subtitle":"Gum & Mints","details":"Beemans began in 1898 as a pharmacist's pepsin gum for digestion; pilots later prized the retro black-and-red pack.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beeman%27s_Pepsin_Gum_DSCF1434.jpg?width=1024"},{"name":"Clove Gum","rarity":"common","id":"clove-gum","subtitle":"Gum & Mints","details":"Clove gum, a spiced Adams classic revived for retro shelves, flavors chewing gum with warm clove instead of mint or fruit.","image":"assets/sets/candy/images/clove-gum.webp"},{"name":"Bubble Yum Watermelon Gum","rarity":"common","id":"bubble-yum-watermelon-gum","subtitle":"Gum & Mints","details":"Bubble Yum's watermelon chunks keep the brand's soft, easy-blowing chew, flavored like a slice of summer melon.","image":"assets/sets/candy/images/bubble-yum-watermelon-gum.webp"},{"name":"Peeps Original Marshmallow Chicks","rarity":"legendary","id":"peeps-original-marshmallow-chicks","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Marshmallow chicks introduced by Just Born in 1953; the pastel Easter icon, now inseparable from spring baskets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Just_Born_Peeps_in_an_Easter_Basket.jpg?width=1024"},{"name":"Brach's Classic Candy Corn","rarity":"legendary","id":"brachs-classic-candy-corn","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Brach's take on candy corn, the tri-color mellowcreme kernel created in the 1880s and now a Halloween staple.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Candy-Corn.jpg?width=1024"},{"name":"Cadbury Creme Egg","rarity":"legendary","id":"cadbury-creme-egg","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Cadbury's Easter icon: a milk chocolate shell filled with gooey white-and-yolk fondant that mimics a soft egg.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cadbury-Creme-Egg-Whole-%26-Split.jpg?width=1024"},{"name":"Reese's Peanut Butter Pumpkins","rarity":"epic","id":"reeses-peanut-butter-pumpkins","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Reese's Halloween pumpkin shape packs extra peanut butter filling, making it a trick-or-treat favorite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2019-08-12_02_24_36_An_unwrapped_King_Size_pack_of_milk_chocolate_Reese%27s_Peanut_Butter_Pumpkins_in_the_Franklin_Farm_section_of_Oak_Hill%2C_Fairfax_County%2C_Virginia.jpg?width=1024"},{"name":"Reese's Peanut Butter Eggs","rarity":"epic","id":"reeses-peanut-butter-eggs","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Reese's Easter egg shape swaps the cup's ridges for a smooth shell and a generous peanut butter center.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2019-03-27_19_07_44_A_packet_of_milk_chocolate_Reese%27s_Peanut_Butter_Eggs_in_Dunn_Loring%2C_Fairfax_County%2C_Virginia.jpg?width=1024"},{"name":"Reese's Peanut Butter Trees","rarity":"rare","id":"reeses-peanut-butter-trees","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Reese's Christmas tree shape gives the peanut butter cup a holiday mold with a rich filling-to-chocolate ratio.","image":"https://images.openfoodfacts.org/images/products/003/400/047/8071/front_fr.8.400.jpg"},{"name":"Whoppers Robin Eggs","rarity":"rare","id":"whoppers-robin-eggs","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Speckled pastel malted milk balls shaped like tiny eggs; a crunchy Whoppers spin made for Easter baskets.","image":"assets/sets/candy/images/whoppers-robin-eggs.webp"},{"name":"Cadbury Mini Eggs","rarity":"rare","id":"cadbury-mini-eggs","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Cadbury milk chocolate eggs in a crisp sugar shell, a small, crunchy Easter basket essential.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A_group_of_Cadbury_Mini_Eggs.jpg?width=1024"},{"name":"Brach's Mellowcreme Pumpkins","rarity":"rare","id":"brachs-mellowcreme-pumpkins","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Brach's mellowcreme pumpkins bring candy corn's honeyed sweetness into plump orange Halloween shapes.","image":"https://upload.wikimedia.org/wikipedia/commons/d/dc/Candy_corn_and_candy_pumpkins_closeup%2C_October_2006.jpg"},{"name":"Caramel Apple Pops","rarity":"rare","id":"caramel-apple-pops","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Green apple hard candy wrapped in golden caramel, built to taste like a fairground caramel apple on a stick.","image":"assets/sets/candy/images/caramel-apple-pops.webp"},{"name":"Bob's Peppermint Candy Canes","rarity":"rare","id":"bobs-peppermint-candy-canes","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Bob's peppermint candy canes, the red-and-white striped Christmas classic for trees, stockings and cocoa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Candy-Cane-Classic.jpg?width=1024"},{"name":"Sweethearts Conversation Hearts","rarity":"rare","id":"sweethearts-conversation-hearts","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Valentine's Day hearts stamped with short love notes; their printed-message idea dates to the 1860s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Necco-Candy-SweetHearts.jpg?width=1024"},{"name":"Hershey's Kisses Candy Cane","rarity":"rare","id":"hersheys-kisses-candy-cane","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Hershey's white creme Kisses studded with red peppermint candy bits, released for the Christmas season.","image":"https://upload.wikimedia.org/wikipedia/commons/1/13/Candy_Cane_Hershey%27s_Kisses_%2824080235996%29.jpg"},{"name":"Kit Kat Witch's Brew","rarity":"rare","id":"kit-kat-witchs-brew","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Kit Kat's Halloween wafer coated in green marshmallow-flavored creme, colored like a witch's potion.","image":"assets/sets/candy/images/kit-kat-witchs-brew.webp"},{"name":"Skittles Shriekers","rarity":"rare","id":"skittles-shriekers","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Skittles' Halloween mix hides shockingly sour pieces among the sweet ones, so any handful can ambush you.","image":"https://images.openfoodfacts.org/images/products/002/200/033/3148/front_en.3.400.jpg"},{"name":"Peeps Marshmallow Ghosts","rarity":"rare","id":"peeps-marshmallow-ghosts","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Peeps' white marshmallow ghosts trade Easter pastels for a simple, spooky Halloween shape.","image":"assets/sets/candy/images/peeps-marshmallow-ghosts.webp"},{"name":"Russell Stover Marshmallow Egg","rarity":"rare","id":"russell-stover-marshmallow-egg","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Russell Stover's Easter staple: fluffy marshmallow sealed inside a milk chocolate egg shell.","image":"assets/sets/candy/images/russell-stover-marshmallow-egg.webp"},{"name":"M&M's White Chocolate Peppermint","rarity":"rare","id":"m-ms-white-chocolate-peppermint","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"M&M's white chocolate peppermint candies in red-and-white shells, made for the Christmas candy dish.","image":"https://images.openfoodfacts.org/images/products/063/791/378/7690/front_fr.9.400.jpg"},{"name":"Nik-L-Nip Wax Bottles","rarity":"epic","id":"nik-l-nip-wax-bottles","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Tiny wax soda bottles filled with sweet syrup: bite off the top, drink the juice, then chew the wax.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nik-L-Nip-Bottles.jpg?width=1024"},{"name":"Wack-O-Wax Wax Lips","rarity":"rare","id":"wack-o-wax-wax-lips","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Cherry-flavored oversized wax lips you wear for a goofy grin, then chew; a Halloween novelty classic.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b8/Waxlips.JPG"},{"name":"Fun Dip Cherry Yum Diddly Dip","rarity":"epic","id":"fun-dip-cherry-yum-diddly-dip","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Fun Dip's cherry powder eaten with a vanilla Lik-a-Stix dipping stick; pure sweet-tart spoon-free fun.","image":"https://images.openfoodfacts.org/images/products/007/920/000/5795/front_en.11.400.jpg"},{"name":"Fun Dip Razz Apple Magic Dip","rarity":"uncommon","id":"fun-dip-razz-apple-magic-dip","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Fun Dip's blue raspberry-apple powder paired with a vanilla dipping stick for lick, dip and crunch.","image":"assets/sets/candy/images/fun-dip-razz-apple-magic-dip.webp"},{"name":"Baby Bottle Pop Strawberry","rarity":"epic","id":"baby-bottle-pop-strawberry","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"A strawberry lollipop top you dip into sour-sweet powder, shaped like a baby bottle for novelty appeal.","image":"assets/sets/candy/images/baby-bottle-pop-strawberry.webp"},{"name":"Pop Rocks Strawberry","rarity":"epic","id":"pop-rocks-strawberry","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Strawberry candy packed with carbon dioxide bubbles, so it crackles and pops as it melts on your tongue.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pop-Rocks.jpg?width=1024"},{"name":"Pop Rocks Tropical Punch","rarity":"uncommon","id":"pop-rocks-tropical-punch","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Pop Rocks in tropical punch flavor, delivering the same fizzy snap from pressurized candy crystals.","image":"https://images.openfoodfacts.org/images/products/072/187/400/4009/front_fr.9.400.jpg"},{"name":"Pixy Stix Grape","rarity":"uncommon","id":"pixy-stix-grape","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Grape-flavored sweet-tart powder poured straight from a paper straw; Pixy Stix began as a drink mix idea.","image":"https://images.openfoodfacts.org/images/products/007/920/082/9056/front_fr.3.400.jpg"},{"name":"Razzles Original","rarity":"uncommon","id":"razzles-original","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"First it's a candy, then it's a gum: Razzles, introduced in 1966, start as tablets and chew into gum.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Razzles.jpg?width=1024"},{"name":"Gold Mine Nugget Bubble Gum","rarity":"uncommon","id":"gold-mine-nugget-bubble-gum","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Chunks of gold-colored bubble gum sold in a little drawstring pouch, like nuggets from a gold mine.","image":"https://images.openfoodfacts.org/images/products/079/805/101/2249/front_fr.3.400.jpg"},{"name":"Choward's Violet Squares","rarity":"uncommon","id":"chowards-violet-squares","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Choward's floral violet-flavored squares, a perfumed old-time candy sold in its signature purple pack.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Choward%27s_Violet_Mints_-_opened.jpg?width=1024"},{"name":"Altoids Sours Tangerine","rarity":"uncommon","id":"altoids-sours-tangerine","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Altoids' intensely sour tangerine hard candies, discontinued in 2010 and still chased by cult fans.","image":"assets/sets/candy/images/altoids-sours-tangerine.webp"},{"name":"Creme Savers Strawberries & Creme","rarity":"uncommon","id":"creme-savers-strawberries-creme","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Swirled strawberry-and-cream hard candies, discontinued then revived in 2021 after years of fan demand.","image":"https://images.openfoodfacts.org/images/products/085/991/700/4409/front_en.9.400.jpg"},{"name":"Bonkers Strawberry","rarity":"uncommon","id":"bonkers-strawberry","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Nabisco's chewy strawberry Bonkers from the 1980s, remembered for giant fruit crashing its commercials.","image":"assets/sets/candy/images/bonkers-strawberry.webp"},{"name":"Dweebs Sweet & Tart","rarity":"uncommon","id":"dweebs-sweet-tart","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Wonka's 1990s Dweebs were bigger, softer cousins of Nerds, sold in a three-chamber flip-top box. Discontinued.","image":"https://images.openfoodfacts.org/images/products/505/619/241/0672/front_en.3.400.jpg"},{"name":"Sky Bar","rarity":"uncommon","id":"sky-bar","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Introduced in 1938, Sky Bar has four sections with different fillings; revived after NECCO closed in 2018.","image":"assets/sets/candy/images/sky-bar.webp"},{"name":"Wonder Ball","rarity":"uncommon","id":"wonder-ball","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"A hollow chocolate ball hiding a surprise inside; the 1990s favorite was discontinued, then later revived.","image":"https://images.openfoodfacts.org/images/products/004/137/610/1632/front_en.10.400.jpg"},{"name":"Ouch! Sour Watermelon Bubble Gum","rarity":"uncommon","id":"ouch-sour-watermelon-bubble-gum","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Sour watermelon bubble gum shaped like adhesive bandages and sold in a tin. A discontinued 1990s novelty.","image":"assets/sets/candy/images/ouch-sour-watermelon-bubble-gum.webp"},{"name":"Bubble Beeper","rarity":"uncommon","id":"bubble-beeper","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Bubble gum packed in a plastic beeper case, a discontinued novelty from when every kid wanted a pager.","image":"assets/sets/candy/images/bubble-beeper.webp"},{"name":"Dr Pepper Bubble Gum","rarity":"uncommon","id":"dr-pepper-bubble-gum","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Bubble gum with a liquid Dr Pepper-flavored center, bottling soda-fountain flavor in a chew. Discontinued.","image":"assets/sets/candy/images/dr-pepper-bubble-gum.webp"},{"name":"Gatorade Gum (Gatorgum)","rarity":"common","id":"gatorade-gum-gatorgum","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Gatorade's Gatorgum promised a thirst-quenching chew in the 1980s, but the sports gum was discontinued.","image":"assets/sets/candy/images/gatorade-gum-gatorgum.webp"},{"name":"Life Savers Holes","rarity":"common","id":"life-savers-holes","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Life Savers Holes sold the candy supposedly punched from the ring's center in 1990, then vanished fast.","image":"assets/sets/candy/images/life-savers-holes.webp"},{"name":"Sodalicious Fruit Snacks","rarity":"common","id":"sodalicious-fruit-snacks","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Betty Crocker's 1990s fruit snacks shaped like soda bottles and flavored like fizzy drinks. Discontinued.","image":"assets/sets/candy/images/sodalicious-fruit-snacks.webp"},{"name":"Butterfinger BB's","rarity":"common","id":"butterfinger-bbs","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Butterfinger in marble-sized BB's, introduced in 1992 and discontinued in 2006 despite Simpsons-era fame.","image":"assets/sets/candy/images/butterfinger-bbs.webp"},{"name":"Reese's Peanut Butter & Banana Creme Cup (Elvis Cup)","rarity":"common","id":"reeses-peanut-butter-banana-creme-cup-elvis-cup","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Reese's 2007 Elvis tribute cup layered peanut butter with banana creme, honoring his famous sandwich.","image":"assets/sets/candy/images/reeses-peanut-butter-banana-creme-cup-elvis-cup.webp"},{"name":"Hershey's Kissables","rarity":"common","id":"hersheys-kissables","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Hershey's candy-coated miniature Kisses, launched in 2005 and discontinued in 2009.","image":"https://upload.wikimedia.org/wikipedia/commons/5/51/Miniture_Hershey_Kisses_%282830832406%29.jpg"},{"name":"Wonka Donutz","rarity":"common","id":"wonka-donutz","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Wonka's chocolate donut-shaped candies topped with sprinkles, a mid-2000s novelty that was discontinued.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wonka_Donutz.png?width=400"},{"name":"Tart 'n' Tinys","rarity":"common","id":"tart-n-tinys","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Wonka's tiny tart candy cylinders from the 1970s; discontinued, then later revived for nostalgic fans.","image":"https://images.openfoodfacts.org/images/products/085/448/800/3943/front_en.4.400.jpg"},{"name":"Wacky Wafers","rarity":"common","id":"wacky-wafers","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Wonka's big coin-shaped fruit wafers, like oversized Bottle Caps; discontinued, then later revived.","image":"https://images.openfoodfacts.org/images/products/085/893/200/5095/front_fr.8.400.jpg"},{"name":"Alexander the Grape","rarity":"common","id":"alexander-the-grape","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Ferrara's grape boxed candy and the grape counterpart in its fruit-head lineup. Now discontinued.","image":"assets/sets/candy/images/alexander-the-grape.webp"},{"name":"Cherry Clan","rarity":"common","id":"cherry-clan","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Ferrara's cherry boxed candy, sibling to Lemonhead with a mascot to match. Now discontinued.","image":"assets/sets/candy/images/cherry-clan.webp"},{"name":"Johnny Apple Treats","rarity":"common","id":"johnny-apple-treats","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Ferrara's apple-flavored boxed candy from its fruit-character family. A discontinued orchard cousin.","image":"assets/sets/candy/images/johnny-apple-treats.webp"},{"name":"Summit Cookie Bar","rarity":"common","id":"summit-cookie-bar","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Mars' Summit bar layered wafers and peanuts under milk chocolate in the late 1970s before being discontinued.","image":"assets/sets/candy/images/summit-cookie-bar.webp"},{"name":"Marathon Bar","rarity":"common","id":"marathon-bar","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Mars' Marathon Bar, sold 1973 to 1981, was an 8-inch braided caramel-chocolate bar with a ruler on its wrapper.","image":"assets/sets/candy/images/marathon-bar.webp"},{"name":"Reggie! Bar","rarity":"common","id":"reggie-bar","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Named for slugger Reggie Jackson and introduced in 1978, this peanut-caramel chocolate bar was discontinued.","image":"assets/sets/candy/images/reggie-bar.webp"},{"name":"Willy Wonka Oompas","rarity":"common","id":"willy-wonka-oompas","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Wonka's Oompas were peanut butter-filled chocolate candies, larger kin to Reese's Pieces. Discontinued.","image":"assets/sets/candy/images/willy-wonka-oompas.webp"},{"name":"Nestlé Alpine White Bar","rarity":"common","id":"nestle-alpine-white-bar","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Nestle's white chocolate bar with chopped almonds, a 1980s premium bar that was later discontinued.","image":"assets/sets/candy/images/nestle-alpine-white-bar.webp"},{"name":"Hershey's BarNone","rarity":"common","id":"hersheys-barnone","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Hershey's BarNone, introduced in 1987, layered a chocolate wafer, peanuts and caramel; revived after discontinuation.","image":"assets/sets/candy/images/hersheys-barnone.webp"},{"name":"PB Max","rarity":"common","id":"pb-max","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Mars' PB Max put peanut butter cream on a whole-grain cookie under milk chocolate; discontinued in the 1990s.","image":"assets/sets/candy/images/pb-max.webp"},{"name":"Seven Up Bar","rarity":"common","id":"seven-up-bar","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Pearson's Seven Up Bar, made from the 1930s to 1979, hid seven different filled sections in one chocolate bar.","image":"assets/sets/candy/images/seven-up-bar.webp"},{"name":"Chicken Dinner Bar","rarity":"common","id":"chicken-dinner-bar","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Sperry's 1920s chocolate peanut bar named for the promise of prosperity; it contained no chicken. Gone by the 1960s.","image":"assets/sets/candy/images/chicken-dinner-bar.webp"},{"name":"Milkshake Bar (Hollywood Candies)","rarity":"common","id":"milkshake-bar-hollywood-candies","subtitle":"Novelty, Seasonal & Gone-But-Not-Forgotten","details":"Hollywood Candies' malted chocolate bar meant to taste like a frozen milkshake; a discontinued mid-century treat.","image":"assets/sets/candy/images/milkshake-bar-hollywood-candies.webp"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
